/**
 * Bottom sheets are surfaces containing supplementary content that are anchored to the bottom of the screen.
 *
 * - {@link https://livingdesign.walmart.com/components/bottom-sheet/ Guidelines}
 * - {@link https://livingdesign.walmart.com/components/bottom-sheet/react/ React documentation}
 *
 * ### A11y label
 *
 * The Bottom Sheet accepts a required accessible label through the `a11yLabel` prop if a `title` prop is not present and vice versa:
 *
 * ```tsx
 * <BottomSheet
 *   a11yLabel="Bottom Sheet Label"
 *   onClose={() => setIsOpen(false)}
 * >
 *   Content
 * </BottomSheet>
 * ```
 *
 * ### Actions
 *
 * The Bottom Sheet accepts actions through an optional `actions` prop:
 *
 * ```tsx
 * <BottomSheet
 *   actions={
 *     <ButtonGroup>
 *       <Button>Action 1</Button>
 *       <Button>Action 2</Button>
 *     </ButtonGroup>
 *   }
 *   onClose={() => setIsOpen(false)}
 *   title="Bottom Sheet Title"
 * >
 *   Content
 * </BottomSheet>
 * ```
 *
 * ### Content
 *
 * The Bottom Sheet accepts content through the `children` prop:
 *
 * ```tsx
 * <BottomSheet
 *   onClose={() => setIsOpen(false)}
 *   title="Bottom Sheet Title"
 * >
 *   Content
 * </BottomSheet>
 * ```
 *
 * ### Opening and closing
 *
 * The Bottom Sheet is set to open or close based on the `isOpen` prop. The logic for closing the Bottom Sheet is controlled through the required `onClose` prop:
 *
 * ```tsx
 * import * as React from "react";
 * import { BottomSheet } from "@walmart-web/livingdesign-components";
 *
 * export default () => {
 *   const [isOpen, setIsOpen] = React.useState(false);
 *   return (
 *     <BottomSheet
 *       isOpen={isOpen}
 *       onClose={() => setIsOpen(false)}
 *       title="Bottom Sheet Title"
 *     >
 *       Content
 *     </BottomSheet>
 *   );
 * }
 * ```
 *
 * ### Title
 *
 * The Bottom Sheet accepts a required title through the `title` prop if an `a11yLabel` prop is not present and vice versa:
 *
 * ```tsx
 * <BottomSheet
 *   onClose={() => setIsOpen(false)}
 *   title="Bottom Sheet Title"
 * >
 *   Content
 * </BottomSheet>
 * ```
 */
